"""Patch the platform folders generated by `flutter create` for MaxStream.

python ci/prepare.py android|windows   (run from app/)
"""
import base64
import os
import re
import shutil
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
APP = os.path.dirname(HERE)


def read(path):
    with open(path, encoding='utf-8') as f:
        return f.read()


def write(path, text):
    with open(path, 'w', encoding='utf-8') as f:
        f.write(text)


def android():
    res_src = os.path.join(HERE, 'android', 'res')
    res_dst = os.path.join(APP, 'android', 'app', 'src', 'main', 'res')
    for folder in os.listdir(res_src):
        os.makedirs(os.path.join(res_dst, folder), exist_ok=True)
        for name in os.listdir(os.path.join(res_src, folder)):
            shutil.copy(os.path.join(res_src, folder, name), os.path.join(res_dst, folder, name))

    manifest_path = os.path.join(APP, 'android', 'app', 'src', 'main', 'AndroidManifest.xml')
    m = read(manifest_path)
    perms = ('    <uses-permission android:name="android.permission.INTERNET"/>\n'
             '    <uses-permission android:name="android.permission.WAKE_LOCK"/>\n'
             '    <uses-feature android:name="android.software.leanback" android:required="false"/>\n'
             '    <uses-feature android:name="android.hardware.touchscreen" android:required="false"/>\n')
    m = re.sub(r'(<manifest[^>]*>\n)', r'\1' + perms, m, count=1)
    m = re.sub(r'android:label="[^"]*"', 'android:label="MaxStream"', m, count=1)
    m = m.replace('<application', '<application\n        android:usesCleartextTraffic="true"\n'
                  '        android:banner="@drawable/banner"', 1)
    m = m.replace('<category android:name="android.intent.category.LAUNCHER"/>',
                  '<category android:name="android.intent.category.LAUNCHER"/>\n'
                  '                <category android:name="android.intent.category.LEANBACK_LAUNCHER"/>', 1)
    write(manifest_path, m)

    # release signing when the keystore secret is available
    ks = os.environ.get('ANDROID_KEYSTORE_B64', '').strip()
    gradle_kts = os.path.join(APP, 'android', 'app', 'build.gradle.kts')
    gradle = os.path.join(APP, 'android', 'app', 'build.gradle')
    if ks:
        ks_path = os.path.join(APP, 'android', 'app', 'maxstream.jks')
        with open(ks_path, 'wb') as f:
            f.write(base64.b64decode(ks))
        pwd = os.environ.get('ANDROID_KEYSTORE_PASSWORD', '')
        alias = os.environ.get('ANDROID_KEY_ALIAS', 'maxstream')
        if os.path.exists(gradle_kts):
            g = read(gradle_kts)
            block = ('    signingConfigs {\n        create("release") {\n'
                     '            storeFile = file("maxstream.jks")\n'
                     '            storePassword = System.getenv("ANDROID_KEYSTORE_PASSWORD")\n'
                     '            keyAlias = "%s"\n'
                     '            keyPassword = System.getenv("ANDROID_KEYSTORE_PASSWORD")\n'
                     '        }\n    }\n\n    buildTypes {' % alias)
            g = g.replace('    buildTypes {', block, 1)
            g = g.replace('signingConfig = signingConfigs.getByName("debug")',
                          'signingConfig = signingConfigs.getByName("release")')
            write(gradle_kts, g)
        else:
            g = read(gradle)
            block = ('    signingConfigs {\n        release {\n'
                     '            storeFile file("maxstream.jks")\n'
                     '            storePassword System.getenv("ANDROID_KEYSTORE_PASSWORD")\n'
                     '            keyAlias "%s"\n'
                     '            keyPassword System.getenv("ANDROID_KEYSTORE_PASSWORD")\n'
                     '        }\n    }\n\n    buildTypes {' % alias)
            g = g.replace('    buildTypes {', block, 1)
            g = g.replace('signingConfig signingConfigs.debug', 'signingConfig signingConfigs.release')
            write(gradle, g)
        print('release signing configured' if pwd else 'WARNING: keystore without password')
    else:
        print('no keystore secret: the APK is signed with the debug key')


def windows():
    shutil.copy(os.path.join(HERE, 'windows', 'app_icon.ico'),
                os.path.join(APP, 'windows', 'runner', 'resources', 'app_icon.ico'))
    main_cpp = os.path.join(APP, 'windows', 'runner', 'main.cpp')
    c = read(main_cpp)
    c = re.sub(r'window\.Create\(L"[^"]*"', 'window.Create(L"MaxStream"', c)
    c = re.sub(r'Win32Window::Size size\(\d+, \d+\)', 'Win32Window::Size size(1600, 900)', c)
    write(main_cpp, c)
    rc_path = os.path.join(APP, 'windows', 'runner', 'Runner.rc')
    rc = read(rc_path)
    rc = re.sub(r'VALUE "FileDescription", "[^"]*"', 'VALUE "FileDescription", "MaxStream IPTV"', rc)
    rc = re.sub(r'VALUE "ProductName", "[^"]*"', 'VALUE "ProductName", "MaxStream"', rc)
    rc = re.sub(r'VALUE "CompanyName", "[^"]*"', 'VALUE "CompanyName", "MaxStreamKodi"', rc)
    write(rc_path, rc)


if __name__ == '__main__':
    {'android': android, 'windows': windows}[sys.argv[1]]()
